(ctx) => {
  const mk = (path, body, what) => { const r = ctx.api('POST', path, body); ctx.assert(r.status === 201, what + ': ' + r.status + ' ' + JSON.stringify(r.body)); return r.body; };
  const expectErr = (r, status, code, what) => ctx.assert(r.status === status && r.body.error && r.body.error.code === code, what + ': ' + JSON.stringify(r));
  const o = mk('/owners', { name: 'Pricing Owner', email: 'pricing.owner@acceptance.example' }, 'owner');
  const o2 = mk('/owners', { name: 'Pricing Stranger', email: 'pricing.stranger@acceptance.example' }, 'stranger owner');
  const w = mk('/walkers', { name: 'Pricing Walker', email: 'pricing.walker@acceptance.example', rate_per_dog: 1500 }, 'walker');
  const d1 = mk('/dogs', { owner_id: o.id, name: 'Biscuit', breed: 'Beagle', size: 'small' }, 'dog 1');
  const d2 = mk('/dogs', { owner_id: o.id, name: 'Mochi', breed: 'Corgi', size: 'small' }, 'dog 2');
  const rex = mk('/dogs', { owner_id: o2.id, name: 'Rex', breed: 'Boxer', size: 'large' }, 'stranger dog');
  const book = (walker, dog, start, mins) => ctx.api('POST', '/bookings', { owner_id: o.id, walker_id: walker.id, dog_id: dog.id, starts_at: start, duration_minutes: mins });
  const r = book(w, d1, '2026-10-07T13:00:00.000Z', 60);
  ctx.assert(r.status === 201, 'book_walk returned ' + r.status + ' ' + JSON.stringify(r.body));
  const b = r.body;
  ctx.assert(b.status === 'booked' && b.price === 3000 && b.dog_count === 1, 'booked, price 3000, one dog, got ' + JSON.stringify(b));
  ctx.assert(b.ends_at === '2026-10-07T14:00:00.000Z' && b.paid === false && b.cancellation_fee === 0, 'ends_at 14:00, unpaid, no fee, got ' + JSON.stringify(b));
  ctx.assert(b.owner_id === o.id && b.walker_id === w.id, 'owner and walker are kept');
  const add = ctx.api('POST', '/bookings/' + b.id + '/add_dog', { dog_id: d2.id });
  ctx.assert(add.status === 200 && add.body.dog_count === 2 && add.body.price === 6000, 'add_dog: ' + JSON.stringify(add));
  const dogs = ctx.api('GET', '/bookings/' + b.id + '/dogs');
  ctx.assert(dogs.status === 200 && dogs.body.data.length === 2, 'two dogs on the booking, got ' + JSON.stringify(dogs.body));
  expectErr(ctx.api('POST', '/bookings/' + b.id + '/add_dog', { dog_id: rex.id }), 422, 'dog_owner_mismatch', 'add other owner dog');
  expectErr(book(w, rex, '2026-10-07T16:00:00.000Z', 60), 422, 'dog_owner_mismatch', 'book with other owner dog');
  expectErr(book(w, d1, '2026-10-07T16:00:00.000Z', 45), 422, 'invalid_duration', 'duration 45');
  expectErr(book(w, d1, '2026-10-07T08:00:00.000Z', 60), 422, 'slot_in_past', 'past slot');
  const w2 = mk('/walkers', { name: 'Sleepy Walker', email: 'pricing.sleepy@acceptance.example', rate_per_dog: 1000 }, 'walker 2');
  const off = ctx.api('PATCH', '/walkers/' + w2.id, { active: false });
  ctx.assert(off.status === 200 && off.body.active === false, 'deactivate walker: ' + JSON.stringify(off));
  expectErr(book(w2, d1, '2026-10-07T16:00:00.000Z', 60), 409, 'walker_inactive', 'inactive walker');
}

(ctx) => {
  const mk = (path, body, what) => { const r = ctx.api('POST', path, body); ctx.assert(r.status === 201, what + ': ' + r.status + ' ' + JSON.stringify(r.body)); return r.body; };
  const o = mk('/owners', { name: 'Overlap Owner', email: 'overlap.owner@acceptance.example' }, 'owner');
  const d1 = mk('/dogs', { owner_id: o.id, name: 'Waffles', breed: 'Poodle', size: 'medium' }, 'dog 1');
  const d2 = mk('/dogs', { owner_id: o.id, name: 'Pickle', breed: 'Pug', size: 'small' }, 'dog 2');
  const w = mk('/walkers', { name: 'Overlap Walker', email: 'overlap.walker@acceptance.example', rate_per_dog: 1000 }, 'walker');
  const w2 = mk('/walkers', { name: 'Overlap Walker Two', email: 'overlap.walker2@acceptance.example', rate_per_dog: 1200 }, 'walker 2');
  const book = (walker, start, mins, dog) => ctx.api('POST', '/bookings', { owner_id: o.id, walker_id: walker.id, dog_id: dog.id, starts_at: start, duration_minutes: mins });
  const b1 = book(w, '2026-10-07T13:00:00.000Z', 60, d1);
  ctx.assert(b1.status === 201, 'first booking: ' + JSON.stringify(b1.body));
  const clash1 = book(w, '2026-10-07T13:30:00.000Z', 30, d2);
  ctx.assert(clash1.status === 409 && clash1.body.error.code === 'walker_unavailable', 'overlap inside: ' + JSON.stringify(clash1));
  const clash2 = book(w, '2026-10-07T12:30:00.000Z', 60, d2);
  ctx.assert(clash2.status === 409 && clash2.body.error.code === 'walker_unavailable', 'overlap at the start: ' + JSON.stringify(clash2));
  ctx.assert(book(w, '2026-10-07T12:00:00.000Z', 60, d2).status === 201, 'slot ending exactly at 13:00 is free');
  ctx.assert(book(w, '2026-10-07T14:00:00.000Z', 30, d2).status === 201, 'slot starting exactly at 14:00 is free');
  ctx.assert(book(w2, '2026-10-07T13:00:00.000Z', 60, d2).status === 201, 'another walker is free at 13:00');
  const c = ctx.api('POST', '/bookings/' + b1.body.id + '/cancel', {});
  ctx.assert(c.status === 200 && c.body.status === 'cancelled', 'cancel first booking: ' + JSON.stringify(c));
  ctx.assert(book(w, '2026-10-07T13:30:00.000Z', 30, d2).status === 201, 'a cancelled booking frees the slot');
}

(ctx) => {
  const mk = (path, body, what) => { const r = ctx.api('POST', path, body); ctx.assert(r.status === 201, what + ': ' + r.status + ' ' + JSON.stringify(r.body)); return r.body; };
  const o = mk('/owners', { name: 'Pack Owner', email: 'pack.owner@acceptance.example' }, 'owner');
  const w = mk('/walkers', { name: 'Pack Walker', email: 'pack.walker@acceptance.example', rate_per_dog: 1000 }, 'walker');
  const names = ['Atlas', 'Bella', 'Cooper', 'Daisy', 'Echo'];
  const dogs = names.map((n) => mk('/dogs', { owner_id: o.id, name: n, breed: 'Mixed', size: 'medium' }, 'dog ' + n));
  const r = ctx.api('POST', '/bookings', { owner_id: o.id, walker_id: w.id, dog_id: dogs[0].id, starts_at: '2026-10-07T15:00:00.000Z', duration_minutes: 30 });
  ctx.assert(r.status === 201 && r.body.price === 1000, 'booking: ' + JSON.stringify(r));
  const id = r.body.id;
  const add = (d) => ctx.api('POST', '/bookings/' + id + '/add_dog', { dog_id: d.id });
  ctx.assert(add(dogs[1]).status === 200, 'second dog');
  const dup = add(dogs[1]);
  ctx.assert(dup.status === 409 && dup.body.error.code === 'duplicate_dog', 'duplicate dog: ' + JSON.stringify(dup));
  ctx.assert(add(dogs[2]).status === 200, 'third dog');
  const fourth = add(dogs[3]);
  ctx.assert(fourth.status === 200 && fourth.body.dog_count === 4 && fourth.body.price === 4000, 'fourth dog: ' + JSON.stringify(fourth));
  const fifth = add(dogs[4]);
  ctx.assert(fifth.status === 409 && fifth.body.error.code === 'booking_full', 'fifth dog: ' + JSON.stringify(fifth));
  const after = ctx.api('GET', '/bookings/' + id).body;
  ctx.assert(after.dog_count === 4 && after.price === 4000, 'booking unchanged by the refused add, got ' + JSON.stringify(after));
  const list = ctx.api('GET', '/bookings/' + id + '/dogs').body.data;
  ctx.assert(list.length === 4, 'four booking dogs, got ' + list.length);
}

(ctx) => {
  const mk = (path, body, what) => { const r = ctx.api('POST', path, body); ctx.assert(r.status === 201, what + ': ' + r.status + ' ' + JSON.stringify(r.body)); return r.body; };
  const o = mk('/owners', { name: 'Cancel Owner', email: 'cancel.owner@acceptance.example' }, 'owner');
  const d = mk('/dogs', { owner_id: o.id, name: 'Nova', breed: 'Husky', size: 'large' }, 'dog');
  const make = (tag, start, mins) => {
    const w = mk('/walkers', { name: 'Cancel Walker ' + tag, email: 'cancel.walker.' + tag + '@acceptance.example', rate_per_dog: 1500 }, 'walker ' + tag);
    const r = ctx.api('POST', '/bookings', { owner_id: o.id, walker_id: w.id, dog_id: d.id, starts_at: start, duration_minutes: mins });
    ctx.assert(r.status === 201, 'booking ' + tag + ': ' + JSON.stringify(r.body));
    return r.body;
  };
  const cancel = (b) => ctx.api('POST', '/bookings/' + b.id + '/cancel', { reason: 'Plans changed' });
  const free = make('free', '2026-10-07T13:00:00.000Z', 60);
  const c1 = cancel(free);
  ctx.assert(c1.status === 200 && c1.body.status === 'cancelled' && c1.body.cancellation_fee === 0, 'free cancel: ' + JSON.stringify(c1));
  ctx.assert(c1.body.cancelled_at === '2026-10-07T09:00:00.000Z', 'cancelled_at is now, got ' + c1.body.cancelled_at);
  const nothing = ctx.api('POST', '/bookings/' + free.id + '/pay', { method: 'card' });
  ctx.assert(nothing.status === 409 && nothing.body.error.code === 'nothing_due', 'pay free cancellation: ' + JSON.stringify(nothing));
  const again = cancel(free);
  ctx.assert(again.status === 409 && again.body.error.code === 'invalid_state', 'cancel twice: ' + JSON.stringify(again));
  const edge = make('edge', '2026-10-07T11:00:00.000Z', 60);
  const c2 = cancel(edge);
  ctx.assert(c2.status === 200 && c2.body.cancellation_fee === 0, 'exactly 120 minutes before is free: ' + JSON.stringify(c2));
  const late = make('late', '2026-10-07T10:59:00.000Z', 60);
  const c3 = cancel(late);
  ctx.assert(c3.status === 200 && c3.body.status === 'cancelled' && c3.body.cancellation_fee === 1500, '119 minutes before costs half of 3000: ' + JSON.stringify(c3));
  const soon = make('soon', '2026-10-07T10:00:00.000Z', 60);
  const c4 = cancel(soon);
  ctx.assert(c4.body.cancellation_fee === 1500, 'one hour before costs half: ' + JSON.stringify(c4));
  const short = make('short', '2026-10-07T10:30:00.000Z', 30);
  const c5 = cancel(short);
  ctx.assert(c5.body.cancellation_fee === 750, 'half of a 15.00 walk is 7.50: ' + JSON.stringify(c5));
  const pay = ctx.api('POST', '/bookings/' + late.id + '/pay', { method: 'card' });
  ctx.assert(pay.status === 201 && pay.body.amount === 1500 && pay.body.kind === 'cancellation_fee' && pay.body.booking_id === late.id, 'pay fee: ' + JSON.stringify(pay));
  const paid = ctx.api('GET', '/bookings/' + late.id).body;
  ctx.assert(paid.paid === true, 'booking is marked paid');
  const twice = ctx.api('POST', '/bookings/' + late.id + '/pay', { method: 'card' });
  ctx.assert(twice.status === 409 && twice.body.error.code === 'already_paid', 'pay fee twice: ' + JSON.stringify(twice));
}

(ctx) => {
  const mk = (path, body, what) => { const r = ctx.api('POST', path, body); ctx.assert(r.status === 201, what + ': ' + r.status + ' ' + JSON.stringify(r.body)); return r.body; };
  const expectErr = (r, status, code, what) => ctx.assert(r.status === status && r.body.error && r.body.error.code === code, what + ': ' + JSON.stringify(r));
  const o = mk('/owners', { name: 'Flow Owner', email: 'flow.owner@acceptance.example' }, 'owner');
  const d = mk('/dogs', { owner_id: o.id, name: 'Juno', breed: 'Lab', size: 'large' }, 'dog');
  const w = mk('/walkers', { name: 'Flow Walker', email: 'flow.walker@acceptance.example', rate_per_dog: 1500 }, 'walker');
  const w2 = mk('/walkers', { name: 'Flow Walker Two', email: 'flow.walker2@acceptance.example', rate_per_dog: 1500 }, 'walker 2');
  const book = (walker, start) => { const r = ctx.api('POST', '/bookings', { owner_id: o.id, walker_id: walker.id, dog_id: d.id, starts_at: start, duration_minutes: 60 }); ctx.assert(r.status === 201, 'booking: ' + JSON.stringify(r.body)); return r.body; };
  const a = book(w, '2026-10-07T10:00:00.000Z');
  const later = book(w2, '2026-10-07T12:00:00.000Z');
  expectErr(ctx.api('POST', '/bookings/' + a.id + '/start', {}), 409, 'too_early', 'start before the slot');
  expectErr(ctx.api('POST', '/bookings/' + later.id + '/complete', {}), 409, 'invalid_state', 'complete a booked walk');
  ctx.advance('1h');
  const s = ctx.api('POST', '/bookings/' + a.id + '/start', {});
  ctx.assert(s.status === 200 && s.body.status === 'in_progress' && s.body.started_at === '2026-10-07T10:00:00.000Z', 'start: ' + JSON.stringify(s));
  expectErr(ctx.api('POST', '/bookings/' + a.id + '/start', {}), 409, 'invalid_state', 'start twice');
  expectErr(ctx.api('POST', '/bookings/' + a.id + '/cancel', {}), 409, 'invalid_state', 'cancel in progress');
  ctx.advance('45m');
  const still = ctx.api('GET', '/bookings/' + a.id).body;
  ctx.assert(still.status === 'in_progress', 'a started walk is not flagged missed, got ' + still.status);
  const c = ctx.api('POST', '/bookings/' + a.id + '/complete', {});
  ctx.assert(c.status === 200 && c.body.status === 'completed' && c.body.completed_at === '2026-10-07T10:45:00.000Z', 'complete: ' + JSON.stringify(c));
  expectErr(ctx.api('POST', '/bookings/' + a.id + '/complete', {}), 409, 'invalid_state', 'complete twice');
  expectErr(ctx.api('POST', '/bookings/' + a.id + '/cancel', {}), 409, 'invalid_state', 'cancel completed');
}

(ctx) => {
  const mk = (path, body, what) => { const r = ctx.api('POST', path, body); ctx.assert(r.status === 201, what + ': ' + r.status + ' ' + JSON.stringify(r.body)); return r.body; };
  const expectErr = (r, status, code, what) => ctx.assert(r.status === status && r.body.error && r.body.error.code === code, what + ': ' + JSON.stringify(r));
  const o = mk('/owners', { name: 'Payer Owner', email: 'payer.owner@acceptance.example' }, 'owner');
  const d = mk('/dogs', { owner_id: o.id, name: 'Otis', breed: 'Dachshund', size: 'small' }, 'dog');
  const w = mk('/walkers', { name: 'Payer Walker', email: 'payer.walker@acceptance.example', rate_per_dog: 2000 }, 'walker');
  const r = ctx.api('POST', '/bookings', { owner_id: o.id, walker_id: w.id, dog_id: d.id, starts_at: '2026-10-07T10:00:00.000Z', duration_minutes: 30 });
  ctx.assert(r.status === 201 && r.body.price === 2000, 'booking: ' + JSON.stringify(r));
  const id = r.body.id;
  expectErr(ctx.api('POST', '/bookings/' + id + '/pay', { method: 'card' }), 409, 'not_payable', 'pay a booked walk');
  ctx.advance('1h');
  ctx.assert(ctx.api('POST', '/bookings/' + id + '/start', {}).status === 200, 'start');
  expectErr(ctx.api('POST', '/bookings/' + id + '/pay', { method: 'card' }), 409, 'not_payable', 'pay an in-progress walk');
  ctx.advance('30m');
  ctx.assert(ctx.api('POST', '/bookings/' + id + '/complete', {}).status === 200, 'complete');
  const p = ctx.api('POST', '/bookings/' + id + '/pay', { method: 'card' });
  ctx.assert(p.status === 201 && p.body.amount === 2000 && p.body.kind === 'walk' && p.body.booking_id === id && p.body.method === 'card', 'pay: ' + JSON.stringify(p));
  const b = ctx.api('GET', '/bookings/' + id).body;
  ctx.assert(b.paid === true && b.status === 'completed', 'booking is paid and still completed, got ' + JSON.stringify(b));
  expectErr(ctx.api('POST', '/bookings/' + id + '/pay', { method: 'cash' }), 409, 'already_paid', 'pay twice');
  const list = ctx.api('GET', '/payments?booking_id=' + id);
  ctx.assert(list.status === 200 && list.body.data.length === 1 && list.body.data[0].id === p.body.id, 'one payment for the booking, got ' + JSON.stringify(list.body));
}

(ctx) => {
  const mk = (path, body, what) => { const r = ctx.api('POST', path, body); ctx.assert(r.status === 201, what + ': ' + r.status + ' ' + JSON.stringify(r.body)); return r.body; };
  const expectErr = (r, status, code, what) => ctx.assert(r.status === status && r.body.error && r.body.error.code === code, what + ': ' + JSON.stringify(r));
  const o = mk('/owners', { name: 'Late Owner', email: 'late.owner@acceptance.example' }, 'owner');
  const d = mk('/dogs', { owner_id: o.id, name: 'Scout', breed: 'Collie', size: 'medium' }, 'dog');
  const wa = mk('/walkers', { name: 'No Show Walker', email: 'late.walker.a@acceptance.example', rate_per_dog: 1500 }, 'walker a');
  const wb = mk('/walkers', { name: 'Punctual Walker', email: 'late.walker.b@acceptance.example', rate_per_dog: 1500 }, 'walker b');
  const book = (walker) => { const r = ctx.api('POST', '/bookings', { owner_id: o.id, walker_id: walker.id, dog_id: d.id, starts_at: '2026-10-07T10:00:00.000Z', duration_minutes: 30 }); ctx.assert(r.status === 201, 'booking: ' + JSON.stringify(r.body)); return r.body; };
  const a = book(wa);
  const b = book(wb);
  const j1 = ctx.advance('1h25m');
  ctx.assert(j1.jobsFailed.length === 0, 'jobs failed: ' + JSON.stringify(j1.jobsFailed));
  ctx.assert(ctx.api('GET', '/bookings/' + a.id).body.status === 'booked', 'not missed 25 minutes after the slot began');
  const s = ctx.api('POST', '/bookings/' + b.id + '/start', {});
  ctx.assert(s.status === 200 && s.body.status === 'in_progress', 'start 25 minutes late: ' + JSON.stringify(s));
  const j2 = ctx.advance('10m');
  ctx.assert(j2.jobsFailed.length === 0, 'jobs failed: ' + JSON.stringify(j2.jobsFailed));
  const missed = ctx.api('GET', '/bookings/' + a.id).body;
  ctx.assert(missed.status === 'missed' && missed.missed_at !== null && missed.cancellation_fee === 0 && missed.paid === false, 'flagged missed: ' + JSON.stringify(missed));
  ctx.assert(ctx.api('GET', '/bookings/' + b.id).body.status === 'in_progress', 'the started walk stays in_progress');
  expectErr(ctx.api('POST', '/bookings/' + a.id + '/start', {}), 409, 'invalid_state', 'start a missed walk');
  expectErr(ctx.api('POST', '/bookings/' + a.id + '/cancel', {}), 409, 'invalid_state', 'cancel a missed walk');
  expectErr(ctx.api('POST', '/bookings/' + a.id + '/pay', { method: 'card' }), 409, 'not_payable', 'pay a missed walk');
  const list = ctx.api('GET', '/bookings?walker_id=' + wa.id + '&status=missed');
  ctx.assert(list.status === 200 && list.body.data.length === 1, 'one missed booking for the walker, got ' + JSON.stringify(list.body));
}

(ctx) => {
  const o = ctx.api('POST', '/owners', { name: 'Registry Owner', email: 'registry.owner@acceptance.example', phone: '+14155550123' });
  ctx.assert(o.status === 201 && o.body.id, 'create owner: ' + JSON.stringify(o));
  const dup = ctx.api('POST', '/owners', { name: 'Registry Twin', email: 'registry.owner@acceptance.example' });
  ctx.assert(dup.status === 409 && dup.body.error.code === 'field.unique', 'duplicate email: ' + JSON.stringify(dup));
  const d = ctx.api('POST', '/dogs', { owner_id: o.body.id, name: 'Maple', breed: 'Retriever', size: 'large' });
  ctx.assert(d.status === 201 && d.body.owner_id === o.body.id, 'create dog: ' + JSON.stringify(d));
  const bad = ctx.api('POST', '/dogs', { owner_id: 'own_9999', name: 'Ghost', size: 'small' });
  ctx.assert(bad.status === 422 && bad.body.error.code === 'ref.unresolved', 'unknown owner: ' + JSON.stringify(bad));
  const unk = ctx.api('POST', '/dogs', { owner_id: o.body.id, name: 'Spots', size: 'small', color: 'brown' });
  ctx.assert(unk.status === 422 && unk.body.error.code === 'field.unknown', 'unknown field: ' + JSON.stringify(unk));
  const up = ctx.api('PATCH', '/dogs/' + d.body.id, { name: 'Maple Leaf' });
  ctx.assert(up.status === 200 && up.body.name === 'Maple Leaf', 'update dog: ' + JSON.stringify(up));
  const list = ctx.api('GET', '/dogs?owner_id=' + o.body.id);
  ctx.assert(list.status === 200 && list.body.data.length === 1 && list.body.data[0].name === 'Maple Leaf', 'dogs of the owner: ' + JSON.stringify(list.body));
  const w = ctx.api('POST', '/walkers', { name: 'Registry Walker', email: 'registry.walker@acceptance.example', rate_per_dog: 1800 });
  ctx.assert(w.status === 201 && w.body.active === true && w.body.rate_per_dog === 1800, 'create walker: ' + JSON.stringify(w));
  const missing = ctx.api('GET', '/owners/own_9999');
  ctx.assert(missing.status === 404 && missing.body.error.code === 'row.not_found', 'missing owner: ' + JSON.stringify(missing));
  const bk = ctx.api('POST', '/bookings', { owner_id: o.body.id, walker_id: w.body.id, dog_id: d.body.id, starts_at: '2026-10-07T12:00:00.000Z', duration_minutes: 30 });
  ctx.assert(bk.status === 201 && bk.body.price === 1800 && bk.body.status === 'booked', 'book the registered dog: ' + JSON.stringify(bk));
}
